-- Undo the job order matrix for Device Repair: removes its jobs and
-- questions and restores the original placeholder question.
-- Generated by backend/scripts/jobMatrixToSql.ts. Runs in one transaction.
-- Stops without changing anything if a booking already uses one of the jobs.
-- City price caps widened by the apply file are left as they are.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "Booking" b JOIN "ServiceTask" t ON t.id = b."serviceTaskId" WHERE t."serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair')) THEN
    RAISE EXCEPTION 'A booking uses a Device Repair job; deactivate the jobs in the admin editor instead.';
  END IF;
END $$;

-- Jobs go first (worker prices, selections and question links cascade with them).
DELETE FROM "ServiceTask" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair');
DELETE FROM "ServiceScopeField" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair');

INSERT INTO "ServiceScopeField" (id, "serviceTypeId", label, "fieldType", required, "sortOrder", "updatedAt")
VALUES ('c25dfba3541d6c309195df279', (SELECT id FROM "ServiceType" WHERE name = 'Device Repair'), 'Computer Repair', 'TEXT', true, 0, NOW());

UPDATE "ServiceType" SET "basePrice" = 1500 WHERE name = 'Device Repair';

SELECT
  (SELECT COUNT(*) FROM "ServiceTask" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair')) AS jobs,            -- expect 0
  (SELECT COUNT(*) FROM "ServiceScopeField" WHERE "serviceTypeId" = (SELECT id FROM "ServiceType" WHERE name = 'Device Repair')) AS questions; -- expect 1

COMMIT;
